package com.autocare.platform.order;

import com.autocare.platform.common.write.WriteIntegrityService;
import com.autocare.platform.service.MerchantActor;
import com.autocare.platform.vehicle.VehicleOwner;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.nio.file.Path;
import java.time.*;
import java.time.temporal.ChronoUnit;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.core.io.FileSystemResource;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import org.springframework.jdbc.datasource.init.ScriptUtils;
import org.springframework.web.server.ResponseStatusException;
import org.testcontainers.containers.MySQLContainer;
import org.testcontainers.junit.jupiter.*;
import static org.junit.jupiter.api.Assertions.*;

@Testcontainers
class JdbcOrderRefundsTest {
    @Container static MySQLContainer<?> mysql=new MySQLContainer<>("mysql:8.0").withCommand("--log-bin-trust-function-creators=1");
    static JdbcTemplate jdbc;
    static class Time extends Clock {Instant value=Instant.now().truncatedTo(ChronoUnit.SECONDS);public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId zone){return this;}public Instant instant(){return value;}}
    PaymentService payments;Time clock;ReservationStore db;ReservationSlots slots;ReservationOrders orders;ReservationExpiry expiry;MerchantActor shop;VehicleOwner a,b;
    @BeforeAll static void schema()throws Exception{
        var ds=new DriverManagerDataSource(mysql.getJdbcUrl(),mysql.getUsername(),mysql.getPassword());jdbc=new JdbcTemplate(ds);
        try(var c=ds.getConnection();var paths=java.nio.file.Files.list(Path.of("..","docs","sql","migrations"))){for(var file:paths.filter(p->p.toString().endsWith(".sql")).sorted().toList())ScriptUtils.executeSqlScript(c,new FileSystemResource(file));ScriptUtils.executeSqlScript(c,new FileSystemResource(Path.of("..","docs","sql","migrations","V025__order_refunds.sql")));}
    }
    @BeforeEach void setup(){
        jdbc.update("DELETE FROM merchant_commission_entry");jdbc.update("DELETE FROM order_commission_snapshot");jdbc.update("DELETE FROM merchant_commission_policy");

        jdbc.execute("DROP TRIGGER IF EXISTS reject_reservation_audit");
        for(String t:List.of("refund_event","refund","order_dispute_record","order_dispute","pickup_check_file","pickup_check","order_status_transition","payment_event","payment_exception","payment","audit_log","idempotency_record","order","appointment_slot","merchant_project_version","merchant_project","standard_project","auth_session","staff_account","merchant","vehicle","user"))jdbc.update("DELETE FROM `"+t+"`");
        clock=new Time();var mapper=new ObjectMapper();var manager=new DataSourceTransactionManager(jdbc.getDataSource());db=new ReservationStore(jdbc,mapper,new WriteIntegrityService(jdbc,mapper,manager),clock,manager);expiry=new ReservationExpiry(db);slots=new ReservationSlots(db);orders=new ReservationOrders(db,expiry);payments=new PaymentService(db,expiry,new PaymentChannels(new LocalTestPaymentChannel(LocalTestPaymentChannelTest.KEY,clock)));
        jdbc.update("INSERT INTO merchant(id,merchant_type,name,address,status) VALUES(1,2,'测试店','合成地址',1)");jdbc.update("INSERT INTO staff_account(id,merchant_id,role,account) VALUES(1,1,'MERCHANT','test')");
        shop=new MerchantActor(1,1,UUID.randomUUID().toString(),Instant.now().plusSeconds(3600));session(shop.session(),"staff_account",1,"MERCHANT","merchant-account",1);
        jdbc.update("INSERT INTO user(id,openid,status) VALUES(1,'owner-a',1),(2,'owner-b',1)");a=owner(1);b=owner(2);
        jdbc.update("INSERT INTO vehicle(id,user_id,model_id,vin,current_mileage) VALUES(1,1,1,'TEST-A',0),(2,2,1,'TEST-B',0)");
        jdbc.update("INSERT INTO standard_project(id,project_name,category,service_content,base_price_low,base_price_high) VALUES(1,'测试项目',1,'测试',1,100)");
        jdbc.update("INSERT INTO merchant_project(id,merchant_id,project_id,price,on_shelf) VALUES(1,1,1,12.34,1)");jdbc.update("INSERT INTO merchant_project_version(id,merchant_project_id,version,price,on_shelf,actor_staff_id) VALUES(1,1,1,12.34,1,1)");
    }
    void session(String id,String type,long subject,String role,String app,long merchant){jdbc.update("INSERT INTO auth_session(id,subject_type,subject_id,role,app_id,merchant_id,refresh_hash,expires_at) VALUES(?,?,?,?,?,?,?,DATE_ADD(UTC_TIMESTAMP(),INTERVAL 1 HOUR))",id,type,subject,role,app,merchant,UUID.randomUUID().toString());}
    VehicleOwner owner(long id){var o=new VehicleOwner(id,UUID.randomUUID().toString(),Instant.now().plusSeconds(3600));session(o.session(),"user",id,"OWNER","test",0);return o;}
    String key(){return UUID.randomUUID().toString();}
    long slot(int capacity){Instant start=clock.value.atZone(ReservationInput.ZONE).toLocalDate().plusDays(1).atTime(10,0).atZone(ReservationInput.ZONE).toInstant();return slots.publish(shop,key(),new ReservationInput.Slot(1,start,start.plusSeconds(3600),capacity)).path("data").path("slot_id").asLong();}
    ReservationInput.Booking booking(VehicleOwner o,long slot){return new ReservationInput.Booking(1,1,o.id(),slot);}
    long order(VehicleOwner o,long slot){return orders.create(o,key(),booking(o,slot)).path("data").path("order_id").asLong();}
    int count(String table){return jdbc.queryForObject("SELECT COUNT(*) FROM `"+table+"`",Integer.class);}
    long pay(long order){return payments.create(a,key(),order,"LOCAL_TEST").path("data").path("payment_id").asLong();}
    PaymentNotice notice(long id,String status,String event,String transaction){var row=jdbc.queryForMap("SELECT p.amount,o.order_no FROM payment p JOIN `order` o ON o.id=p.order_id WHERE p.id=?",id);return new PaymentNotice(event,id,transaction,status,(java.math.BigDecimal)row.get("amount"),"CNY",row.get("order_no").toString(),clock.value,event+status+transaction);}
    void send(long id,String status){payments.notify(notice(id,status,key(),"test-"+id));}
    String state(long id){return payments.detail(a,id).get("status").toString();}

    OrderRefunds refunds(){return new OrderRefunds(db,payments,new RefundChannels(new LocalTestRefundChannel(LocalTestPaymentChannelTest.KEY,clock,"")));}
    long paid(){long o=order(a,slot(2));long p=pay(o);send(p,"SUCCEEDED");return o;}
    long request(long o){return refunds().request(a,key(),o,"申请全额退款").path("data").path("refund").path("refund_id").asLong();}
    void approve(long o){refunds().decide(shop,key(),o,1,"ACCEPT",null);}
    RefundChannel.Notice receipt(long r,String status,String event,String transaction){var row=jdbc.queryForMap("SELECT * FROM refund WHERE id=?",r);return new RefundChannel.Notice(event,r,row.get("refund_no").toString(),ReservationStore.number(row,"payment_id"),transaction,status,(java.math.BigDecimal)row.get("amount"),"CNY",clock.value,event+status+transaction);}
    RefundRecovery recovery(java.util.function.Function<RefundChannel.Request,RefundChannel.Result> query,java.util.function.Function<RefundChannel.Request,RefundChannel.Result> submit){var channel=new LocalTestRefundChannel(LocalTestPaymentChannelTest.KEY,clock,""){
        public boolean canTransact(){return true;}public Result query(Request r){assertFalse(org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive());return query.apply(r);}public Result submit(Request r){assertFalse(org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive());return submit.apply(r);}
    };return new RefundRecovery(new OrderRefunds(db,payments,new RefundChannels(channel)),true);}
    String refundState(long r){return jdbc.queryForObject("SELECT status FROM refund WHERE id=?",String.class,r);}
    @Test void bothAgreeFullRefundClosesAndReleasesWithoutDeclaringFunds(){long o=paid();String k=key();var result=refunds().request(a,k,o,"原因");long r=result.path("data").path("refund").path("refund_id").asLong();assertEquals("PAID",orders.detail(a,o).get("status"));assertEquals(result,refunds().request(a,k,o,"原因"));assertThrows(ResponseStatusException.class,()->request(o));String decision=key();var done=refunds().decide(shop,decision,o,1,"ACCEPT",null);assertEquals(done,refunds().decide(shop,decision,o,1,"ACCEPT",null));assertEquals("12.34",done.path("data").path("refund").path("amount").asText());assertEquals("PENDING",refundState(r));assertEquals("CLOSED",orders.detail(a,o).get("status"));assertEquals("REFUND_CANCELLED",jdbc.queryForObject("SELECT close_reason FROM `order`",String.class));assertEquals(0,jdbc.queryForObject("SELECT reserved_count FROM appointment_slot",Integer.class));assertEquals(1,count("refund"));assertEquals(1,count("order_status_transition"));assertNull(jdbc.queryForObject("SELECT refunded_at FROM refund",Object.class));assertFalse(done.toString().contains("merchant_actor"));}
    @Test void rejectionWithdrawalAndNewRevisionCannotAcceptOldApplication(){long o=paid();request(o);refunds().decide(shop,key(),o,1,"REJECT","需重新确认");assertEquals("PAID",orders.detail(a,o).get("status"));refunds().request(a,key(),o,"新原因");assertEquals(409,assertThrows(ResponseStatusException.class,()->refunds().decide(shop,key(),o,1,"ACCEPT",null)).getStatusCode().value());refunds().withdraw(a,key(),o,3);refunds().request(a,key(),o,"再次申请");refunds().decide(shop,key(),o,5,"ACCEPT",null);assertEquals(1,count("refund"));assertThrows(ResponseStatusException.class,()->refunds().withdraw(a,key(),o,6));}
    @Test void ownerManagerAndSessionBoundaries(){long o=paid(),r=request(o);assertEquals(404,assertThrows(ResponseStatusException.class,()->refunds().detail(b,null,o)).getStatusCode().value());assertEquals(404,assertThrows(ResponseStatusException.class,()->refunds().request(b,key(),o,"私有")).getStatusCode().value());var staff=new MerchantActor(shop.staffId(),1,"STAFF",shop.session(),shop.expires());assertEquals(403,assertThrows(ResponseStatusException.class,()->refunds().decide(staff,key(),o,1,"ACCEPT",null)).getStatusCode().value());assertEquals(403,assertThrows(ResponseStatusException.class,()->refunds().detail(null,staff,o)).getStatusCode().value());jdbc.update("UPDATE auth_session SET revoked_at=UTC_TIMESTAMP() WHERE id=?",shop.session());assertEquals(401,assertThrows(ResponseStatusException.class,()->approve(o)).getStatusCode().value());assertEquals("REQUESTED",refundState(r));}
    @Test void stateChangeRequiresWithdrawAndNewConsent(){long o=paid();request(o);jdbc.update("UPDATE `order` SET status='RECEIVED' WHERE id=?",o);assertEquals(409,assertThrows(ResponseStatusException.class,()->approve(o)).getStatusCode().value());refunds().withdraw(a,key(),o,1);refunds().request(a,key(),o,"重新同意");refunds().decide(shop,key(),o,3,"ACCEPT",null);assertEquals("CLOSED",orders.detail(a,o).get("status"));}
    @Test void allServiceStatusesCanCancelOnlyWithBothParties(){for(String status:OrderRefunds.ELIGIBLE){setup();long o=paid();jdbc.update("UPDATE `order` SET status=? WHERE id=?",status,o);request(o);approve(o);assertEquals("CLOSED",orders.detail(a,o).get("status"));}}
    @Test void unpaidCompletedClosedAndCorruptedPaymentCannotRequest(){long o=paid();for(String status:List.of("PENDING_PAYMENT","COMPLETED","CLOSED")){jdbc.update("UPDATE `order` SET status=? WHERE id=?",status,o);assertThrows(ResponseStatusException.class,()->request(o));}jdbc.update("UPDATE `order` SET status='PAID'");jdbc.update("UPDATE payment SET amount=0.01");assertThrows(ResponseStatusException.class,()->request(o));jdbc.update("UPDATE payment SET amount=12.34");jdbc.update("DELETE FROM payment_event");assertThrows(ResponseStatusException.class,()->request(o));assertEquals(0,count("refund"));}
    @Test void legacyOrSoftDeletedRefundNeverPermitsAnotherRefund(){long o=paid();jdbc.update("INSERT INTO refund(order_id,payment_id,amount,status,is_deleted) VALUES(?,?,12.34,'SUCCEEDED',1)",o,jdbc.queryForObject("SELECT id FROM payment",Long.class));assertThrows(ResponseStatusException.class,()->request(o));assertEquals(1,count("refund"));}
    @Test void paymentExceptionBlocksApprovalAndRequest(){long o=paid();jdbc.update("INSERT INTO payment_exception(payment_id,order_id,channel,amount,reason) VALUES(?,?,'LOCAL_TEST',12.34,'TEST')",jdbc.queryForObject("SELECT id FROM payment",Long.class),o);assertThrows(ResponseStatusException.class,()->request(o));jdbc.update("DELETE FROM payment_exception");request(o);jdbc.update("INSERT INTO payment_exception(payment_id,order_id,channel,amount,reason) VALUES(?,?,'LOCAL_TEST',12.34,'TEST')",jdbc.queryForObject("SELECT id FROM payment",Long.class),o);assertThrows(ResponseStatusException.class,()->approve(o));assertEquals("PAID",orders.detail(a,o).get("status"));}
    @Test void approvalAuditFailureRollsBackOrderCapacityAndAgreement(){long o=paid(),r=request(o);jdbc.execute("CREATE TRIGGER reject_reservation_audit BEFORE INSERT ON audit_log FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='test failure'");assertThrows(ResponseStatusException.class,()->approve(o));assertEquals("REQUESTED",refundState(r));assertEquals("PAID",orders.detail(a,o).get("status"));assertEquals(1,jdbc.queryForObject("SELECT reserved_count FROM appointment_slot",Integer.class));assertNull(jdbc.queryForObject("SELECT merchant_consented_at FROM refund",Object.class));assertEquals(0,count("order_status_transition"));}
    @Test void concurrentApprovalClosesOnlyOnce()throws Exception{long o=paid(),r=request(o);var pool=Executors.newFixedThreadPool(2);try{var x=pool.submit(()->approve(o));var y=pool.submit(()->{try{approve(o);}catch(ResponseStatusException e){assertEquals(409,e.getStatusCode().value());}});try{x.get(20,TimeUnit.SECONDS);}catch(ExecutionException e){assertTrue(e.getCause() instanceof ResponseStatusException);}y.get(20,TimeUnit.SECONDS);assertEquals("PENDING",refundState(r));assertEquals(1,count("order_status_transition"));}finally{pool.shutdownNow();}}
    @Test void duplicateAndOutOfOrderReceiptsNeverReverseSuccess(){long o=paid(),r=request(o);approve(o);var worker=recovery(q->new RefundChannel.Result(true,null),q->{fail();return null;});var n=receipt(r,"SUCCEEDED",key(),"refund-transaction");worker.notify(n);worker.notify(n);worker.notify(receipt(r,"FAILED",key(),"refund-transaction"));worker.notify(receipt(r,"SUCCEEDED",key(),"refund-transaction"));assertEquals("SUCCEEDED",refundState(r));assertEquals(3,count("refund_event"));assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM audit_log WHERE action='REFUND_SUCCEEDED'",Integer.class));assertEquals("CLOSED",orders.detail(a,o).get("status"));}
    @Test void callbackBeforeAgreementAndAmountMismatchNeverPersist(){long o=paid(),r=request(o);var worker=recovery(q->new RefundChannel.Result(true,null),q->null);assertThrows(ResponseStatusException.class,()->worker.notify(receipt(r,"SUCCEEDED",key(),"invalid")));approve(o);var n=receipt(r,"SUCCEEDED",key(),"invalid");assertThrows(ResponseStatusException.class,()->worker.notify(new RefundChannel.Notice(n.eventId(),r,n.refundNo(),n.paymentId(),n.transaction(),n.status(),new java.math.BigDecimal("0.01"),n.currency(),n.occurred(),n.hash())));assertEquals("PENDING",refundState(r));assertEquals(0,count("refund_event"));}
    @Test void providerTimeoutIsQueriedOnNewWorkerBeforeSubmittingAgain(){long o=paid(),r=request(o);approve(o);var submitted=new java.util.concurrent.atomic.AtomicInteger();var known=new java.util.concurrent.atomic.AtomicBoolean();var n=receipt(r,"SUCCEEDED",key(),"timeout-recovery");var query=(java.util.function.Function<RefundChannel.Request,RefundChannel.Result>)q->new RefundChannel.Result(known.get(),known.get()?n:null);var submit=(java.util.function.Function<RefundChannel.Request,RefundChannel.Result>)q->{submitted.incrementAndGet();known.set(true);throw new IllegalStateException("供应商已接受但响应丢失");};recovery(query,submit).sweep();assertEquals("PENDING",refundState(r));clock.value=clock.value.plusSeconds(60);recovery(query,submit).sweep();assertEquals("SUCCEEDED",refundState(r));assertEquals(1,submitted.get());}
    @Test void pendingSupplierAndFailedReceiptNeverCauseSecondSubmit(){long o=paid(),r=request(o);approve(o);var submissions=new java.util.concurrent.atomic.AtomicInteger();var worker=recovery(q->new RefundChannel.Result(true,null),q->{submissions.incrementAndGet();return new RefundChannel.Result(true,null);});worker.sweep();assertEquals(0,submissions.get());worker.notify(receipt(r,"FAILED",key(),"failed-refund"));clock.value=clock.value.plusSeconds(60);worker.sweep();assertEquals("FAILED",refundState(r));worker.notify(receipt(r,"SUCCEEDED",key(),"failed-refund"));assertEquals("SUCCEEDED",refundState(r));}
    @Test void abandonedLeaseAndLateOldWorkerCannotOverwriteNewLease(){long o=paid(),r=request(o);approve(o);var worker=recovery(q->new RefundChannel.Result(true,null),q->null);var old=worker.claim(shop,r);assertNotNull(old);assertNull(worker.claim(shop,r));clock.value=clock.value.plusSeconds(60);var fresh=worker.claim(shop,r);worker.process(old);assertEquals(fresh.token(),jdbc.queryForObject("SELECT dispatch_token FROM refund",String.class));worker.process(fresh);assertNull(jdbc.queryForObject("SELECT dispatch_token FROM refund",String.class));}
    @Test void refundAuditFailureRetriesSameReceipt(){long o=paid(),r=request(o);approve(o);var n=receipt(r,"SUCCEEDED",key(),"retry-audit");var worker=recovery(q->new RefundChannel.Result(true,n),q->null);jdbc.execute("CREATE TRIGGER reject_reservation_audit BEFORE INSERT ON audit_log FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='test failure'");worker.sweep();assertEquals("PENDING",refundState(r));assertEquals(0,count("refund_event"));jdbc.execute("DROP TRIGGER reject_reservation_audit");clock.value=clock.value.plusSeconds(60);worker.sweep();assertEquals("SUCCEEDED",refundState(r));}
    @Test void lateOtherPaymentExceptionDoesNotDiscardApprovedRefundReceipt(){long o=paid(),r=request(o);approve(o);jdbc.update("INSERT INTO payment_exception(payment_id,order_id,channel,amount,reason) VALUES(?,?,'LOCAL_TEST',12.34,'LATE_OTHER_PAYMENT')",jdbc.queryForObject("SELECT id FROM payment",Long.class),o);recovery(q->new RefundChannel.Result(true,null),q->null).notify(receipt(r,"SUCCEEDED",key(),"original-approved"));assertEquals("SUCCEEDED",refundState(r));}

    @Test void otherShopCannotReadOrApproveRefund(){long o=paid();request(o);jdbc.update("INSERT INTO merchant(id,merchant_type,name,address,status) VALUES(2,2,'另一店','合成',1)");jdbc.update("INSERT INTO staff_account(id,merchant_id,role,account) VALUES(2,2,'MERCHANT','other-shop')");var other=new MerchantActor(2,2,key(),Instant.now().plusSeconds(3600));session(other.session(),"staff_account",2,"MERCHANT","merchant-account",2);assertEquals(404,assertThrows(ResponseStatusException.class,()->refunds().detail(null,other,o)).getStatusCode().value());assertEquals(404,assertThrows(ResponseStatusException.class,()->refunds().decide(other,key(),o,1,"ACCEPT",null)).getStatusCode().value());assertEquals("PAID",orders.detail(a,o).get("status"));}
    @Test void changedEventHashAndSupplierTransactionCannotAlterRefund(){long o=paid(),r=request(o);approve(o);var worker=recovery(q->new RefundChannel.Result(true,null),q->null);String event=key();worker.notify(receipt(r,"FAILED",event,"original-transaction"));assertThrows(ResponseStatusException.class,()->worker.notify(receipt(r,"SUCCEEDED",event,"original-transaction")));assertThrows(ResponseStatusException.class,()->worker.notify(receipt(r,"SUCCEEDED",key(),"other-transaction")));assertEquals("FAILED",refundState(r));assertEquals(1,count("refund_event"));}
    @Test void actualSignedSupplierHttpCommitsOriginalRefundInMysql()throws Exception{long o=paid(),r=request(o);approve(o);var n=receipt(r,"SUCCEEDED",key(),"http-refund");var server=com.sun.net.httpserver.HttpServer.create(new java.net.InetSocketAddress("127.0.0.1",0),0);server.createContext("/refunds/",e->{try{var body=new LinkedHashMap<String,Object>();body.put("event_id",n.eventId());body.put("refund_id",r);body.put("refund_no",n.refundNo());body.put("payment_id",n.paymentId());body.put("channel_refund_no",n.transaction());body.put("status",n.status());body.put("amount",n.amount().toPlainString());body.put("currency",n.currency());body.put("occurred_at",n.occurred().toString());byte[] raw=db.mapper.writeValueAsBytes(body);String time=""+clock.instant().getEpochSecond(),nonce=key();e.getResponseHeaders().add("X-Test-Timestamp",time);e.getResponseHeaders().add("X-Test-Nonce",nonce);e.getResponseHeaders().add("X-Test-Signature",LocalTestPaymentChannelTest.sign(raw,time,nonce));e.sendResponseHeaders(200,raw.length);e.getResponseBody().write(raw);}catch(Exception error){throw new RuntimeException(error);}finally{e.close();}});server.start();try{var channel=new LocalTestRefundChannel(LocalTestPaymentChannelTest.KEY,clock,"http://127.0.0.1:"+server.getAddress().getPort());new RefundRecovery(new OrderRefunds(db,payments,new RefundChannels(channel)),true).sweep();assertEquals("SUCCEEDED",refundState(r));assertEquals(1,count("refund_event"));assertEquals("SUCCEEDED",jdbc.queryForObject("SELECT status FROM payment",String.class));}finally{server.stop(0);}}
}
